#include <bits/stdc++.h>
using namespace std;
int n,m,q;
vector<long long> p;
vector<int> LOGT;
vector<vector<long long>> st;
void buildST(){
    LOGT.assign(n+2,0);
    for(int i=2;i<=n+1;i++)LOGT[i]=LOGT[i/2]+1;
    int K=LOGT[n]+1;
    st.assign(K, vector<long long>(n+1));
    for(int i=1;i<=n;i++)st[0][i]=p[i];
    for(int k=1;k<K;k++)for(int i=1;i+(1<<k)-1<=n;i++)
        st[k][i]=min(st[k-1][i], st[k-1][i+(1<<(k-1))]);
}
long long rmq(int l,int r){int k=LOGT[r-l+1];return min(st[k][l],st[k][r-(1<<k)+1]);}
int main(){
    scanf("%d %d %d",&n,&m,&q);
    p.assign(n+1,0);
    for(int i=1;i<=n;i++)scanf("%lld",&p[i]);
    vector<int> a(m);
    for(int i=0;i<m;i++)scanf("%d",&a[i]);
    vector<int> ops; ops.reserve(n-1);
    for(int i=0;i<m;i++){for(int j=0;j<a[i];j++)ops.push_back(0);for(int j=0;j<a[i];j++)ops.push_back(1);}
    buildST();
    vector<int> Ls(n),Ps(n),Qs(n);
    Ls[0]=1;Ps[0]=0;Qs[0]=0;
    for(int x=0;x<n-1;x++){
        int L=Ls[x],P=Ps[x],Q=Qs[x];
        if(ops[x]==0){ if(P<Q)P++; else L++; } else Q++;
        Ls[x+1]=L;Ps[x+1]=P;Qs[x+1]=Q;
    }
    while(q--){
        int x,l,r;scanf("%d %d %d",&x,&l,&r);
        int L=Ls[x],P=Ps[x],Q=Qs[x];
        int K=Q-P+1;
        int lo=l+P, hi=r+Q;
        static vector<long long> W;
        W.assign(hi-lo+2,0);
        for(int j=lo;j<=hi;j++) W[j-lo]=rmq(j,j+L-1);
        int startLo=l+P, startHi=r+P;
        deque<int> dq; long long ans=0;
        int s=startLo;
        for(int j=lo;j<=hi+1;j++){
            if(j<=hi){
                long long v=W[j-lo];
                while(!dq.empty() && W[dq.back()-lo]<=v) dq.pop_back();
                dq.push_back(j);
            }
            int completeJ = (s<=startHi)? (s+K-1): -1;
            if(j==completeJ){
                while(!dq.empty() && dq.front()<s) dq.pop_front();
                ans+=W[dq.front()-lo];
                s++;
            }
        }
        printf("%lld\n",ans);
    }
    return 0;
}
